# SEO blok in de <head>: canonical, hreflang, Open Graph en (op de homepage) JSON-LD.
# Wordt voor elke taal opnieuw gemaakt tussen <!-- seo --> en <!-- /seo -->,
# ook in de Nederlandse pagina's. Pas feiten hieronder aan, niet in de HTML.
# ---------------------------------------------------------------------------
import json, html as _html

SITE = 'https://juultjezeeland.nl/'
DEELBEELD = SITE + 'assets/fotos/deelbeeld-1200.jpg'
DEELBEELD_ALT = 'Woonkamer van het vakantiehuisje met leren bank, eettafel en open keuken'
LOCALE = {'nl': 'nl_NL', 'de': 'de_DE', 'en': 'en_GB'}
TABELLEN = {'nl': None, 'de': DE, 'en': EN}

def t(tekst, taal):
    return tekst if taal == 'nl' else TABELLEN[taal].get(tekst, tekst)

def pagina_url(bestand, taal):
    return SITE + ('' if taal == 'nl' else taal + '/') + ('' if bestand == 'index.html' else bestand)

ADRES = {'@type': 'PostalAddress', 'streetAddress': 'Julianastraat 38', 'postalCode': '4491 GB',
         'addressLocality': 'Wissenkerke', 'addressRegion': 'Zeeland', 'addressCountry': 'NL'}
GEO = {'@type': 'GeoCoordinates', 'latitude': 51.58268, 'longitude': 3.74590}
PRIJZEN = {'nl': '€ 72 tot € 130 per nacht', 'de': '72 € bis 130 € pro Nacht', 'en': '€72 to €130 per night'}
BED = {'nl': 'Tweepersoonsbed', 'de': 'Doppelbett', 'en': 'Double bed'}
ADVERTENTIES = {
    'huisje': ['https://www.booking.com/hotel/nl/vakantiehuisje-juultje-in-wissenkerke.html',
               'https://www.airbnb.nl/rooms/1233409317202963855'],
    'appartement': ['https://www.booking.com/hotel/nl/appartement-in-wissenkerke.html',
                    'https://www.airbnb.nl/rooms/1429527295093271358'],
}
FOTOS = {
    'huisje': ['woonkamer', 'keuken', 'zithoek', 'slaapkamer', 'overkapping', 'bank', 'badkamer', 'oprit'],
    'appartement': ['woonruimte', 'slaapkamer', 'zithoek', 'eettafel', 'keuken', 'badkamer', 'terras', 'douche'],
}

VERBLIJVEN = {
    'huisje': {'soort': 'House', 'id': 3563861, 'naam': 'Vakantiehuisje Juultje', 'm2': 35,
               'bestand': 'vakantiehuisje-wissenkerke.html',
               'extra': ['Eigen parkeerplaats op de oprit', 'Vaatwasser', 'Wasmachine', 'Televisie met Chromecast en Netflix']},
    'appartement': {'soort': 'Apartment', 'id': 3563866, 'naam': 'Appartement Juultje', 'm2': 26,
                    'bestand': 'appartement-wissenkerke.html', 'extra': ['Parkeren in de straat']},
}

def verblijf(taal, sleutel):
    v = VERBLIJVEN[sleutel]
    voorvoegsel = 'vakantiehuisje' if sleutel == 'huisje' else 'appartement'
    return {
        '@type': v['soort'],
        '@id': SITE + '#' + sleutel,
        'name': t(v['naam'], taal),
        'identifier': str(v['id']),
        'url': pagina_url(v['bestand'], taal),
        'image': [SITE + f'assets/fotos/{voorvoegsel}-{f}-1600.jpg' for f in FOTOS[sleutel]],
        'address': ADRES,
        'geo': GEO,
        'occupancy': {'@type': 'QuantitativeValue', 'value': 2},
        'numberOfBedrooms': 1,
        'numberOfBathroomsTotal': 1,
        'bed': {'@type': 'BedDetails', 'numberOfBeds': 1, 'typeOfBed': BED[taal]},
        'floorSize': {'@type': 'QuantitativeValue', 'value': v['m2'], 'unitCode': 'MTK'},
        'petsAllowed': True,
        'amenityFeature': [{'@type': 'LocationFeatureSpecification', 'name': t(n, taal), 'value': True}
                           for n in ['Wifi', 'Airconditioning'] + v['extra']],
        'sameAs': ADVERTENTIES[sleutel],
    }

def kaal(x):
    return _html.unescape(re.sub(r'<[^>]+>', '', x)).strip()

def json_ld_subpagina(taal, bestand, h):
    naam = kaal(re.search(r'<h1>(.*?)</h1>', h, re.S).group(1))
    graaf = [{'@type': 'BreadcrumbList', 'itemListElement': [
        {'@type': 'ListItem', 'position': 1, 'name': 'Juultje Zeeland', 'item': pagina_url('index.html', taal)},
        {'@type': 'ListItem', 'position': 2, 'name': naam, 'item': pagina_url(bestand, taal)}]}]
    vragen = [{'@type': 'Question', 'name': kaal(v), 'acceptedAnswer': {'@type': 'Answer', 'text': kaal(a)}}
              for v, a in re.findall(r'<details class="faq-item"><summary>(.*?)</summary><p>(.*?)</p></details>', h)]
    if vragen:
        graaf.append({'@type': 'FAQPage', '@id': pagina_url(bestand, taal) + '#vragen', 'inLanguage': taal, 'mainEntity': vragen})
    for sleutel, v in VERBLIJVEN.items():
        if v['bestand'] == bestand:
            node = verblijf(taal, sleutel)
            node['containedInPlace'] = {'@id': SITE + '#bedrijf'}
            graaf.append(node)
    data = {'@context': 'https://schema.org', '@graph': graaf}
    return json.dumps(data, ensure_ascii=False, indent=1).replace('</', '<\\/')

def json_ld(taal, beschrijving, h):
    bedrijf = {
        '@type': 'LodgingBusiness',
        '@id': SITE + '#bedrijf',
        'name': 'Juultje Zeeland',
        'description': beschrijving,
        'url': pagina_url('index.html', taal),
        'image': DEELBEELD,
        'telephone': '+31613664239',
        'email': 'juultjeverhuur@gmail.com',
        'address': ADRES,
        'geo': GEO,
        'priceRange': PRIJZEN[taal],
        'currenciesAccepted': 'EUR',
        'paymentAccepted': 'iDEAL, Creditcard, Bancontact, Overschrijving',
        'checkinTime': '15:00',
        'checkoutTime': '10:00',
        'petsAllowed': True,
        'knowsLanguage': ['nl', 'de', 'en'],
        'founder': [{'@type': 'Person', 'name': 'Marc'}, {'@type': 'Person', 'name': 'Angelia'}],
        'sameAs': ['https://www.instagram.com/juultjezeeland'] + [u for l in ADVERTENTIES.values() for u in l],
        'containsPlace': [verblijf(taal, k) for k in VERBLIJVEN],
    }
    site = {'@type': 'WebSite', '@id': SITE + '#site', 'name': 'Juultje Zeeland', 'url': SITE,
            'inLanguage': ['nl', 'de', 'en'], 'publisher': {'@id': SITE + '#bedrijf'}}
    vragen = [{'@type': 'Question', 'name': kaal(v), 'acceptedAnswer': {'@type': 'Answer', 'text': kaal(a)}}
              for v, a in re.findall(r'<details class="faq-item"><summary>(.*?)</summary><p>(.*?)</p></details>', h)]
    graaf = [site, bedrijf]
    if vragen:
        graaf.append({'@type': 'FAQPage', '@id': pagina_url('index.html', taal) + '#vragen',
                      'inLanguage': taal, 'mainEntity': vragen})
    data = {'@context': 'https://schema.org', '@graph': graaf}
    return json.dumps(data, ensure_ascii=False, indent=1).replace('</', '<\\/')

def seo(h, taal, bestand):
    titel = _html.unescape(re.search(r'<title>(.*?)</title>', h).group(1))
    beschrijving = _html.unescape(re.search(r'<meta name="description" content="([^"]*)"', h).group(1))
    e = lambda x: _html.escape(x, quote=True)
    regels = [f'<link rel="canonical" href="{pagina_url(bestand, taal)}">']
    for tl in ('nl', 'de', 'en'):
        regels.append(f'<link rel="alternate" hreflang="{tl}" href="{pagina_url(bestand, tl)}">')
    regels.append(f'<link rel="alternate" hreflang="x-default" href="{pagina_url(bestand, "nl")}">')
    regels += [
        '<meta property="og:type" content="website">',
        '<meta property="og:site_name" content="Juultje Zeeland">',
        f'<meta property="og:title" content="{e(titel)}">',
        f'<meta property="og:description" content="{e(beschrijving)}">',
        f'<meta property="og:url" content="{pagina_url(bestand, taal)}">',
        f'<meta property="og:locale" content="{LOCALE[taal]}">',
    ] + [f'<meta property="og:locale:alternate" content="{LOCALE[a]}">' for a in LOCALE if a != taal] + [
        f'<meta property="og:image" content="{DEELBEELD}">',
        '<meta property="og:image:width" content="1200">',
        '<meta property="og:image:height" content="630">',
        f'<meta property="og:image:alt" content="{e(t(DEELBEELD_ALT, taal))}">',
        '<meta name="twitter:card" content="summary_large_image">',
    ]
    if bestand == 'index.html':
        regels.append('<script type="application/ld+json">\n' + json_ld(taal, beschrijving, h) + '\n</script>')
    elif bestand in PAGINAS:
        regels.append('<script type="application/ld+json">\n' + json_ld_subpagina(taal, bestand, h) + '\n</script>')
    blok = '<!-- seo -->\n' + '\n'.join(regels) + '\n<!-- /seo -->'
    if '<!-- seo -->' in h:
        h, n = re.subn(r'<!-- seo -->.*?<!-- /seo -->', lambda m: blok, h, flags=re.S)
    else:
        h, n = re.subn(r'(?:<link rel="alternate" hreflang="[^"]*" href="[^"]*">\n)+', lambda m: blok + '\n', h, count=1)
    assert n == 1, (bestand, taal, 'plek voor seo blok niet gevonden')
    return h

PAGINAS = ['index.html', 'vakantiehuisje-wissenkerke.html', 'appartement-wissenkerke.html', 'omgeving.html', 'hondenstranden-noord-beveland.html', 'vakantie-met-hond-noord-beveland.html', 'wissenkerke.html', 'fietsroutes-noord-beveland.html', 'zeehonden-oosterschelde.html', 'weekend-noord-beveland-voor-twee.html', 'vakantiehuisje-zeeland.html', 'vakantieappartement-zeeland.html', 'wat-te-doen-zeeland.html', 'zeeland-bij-regen.html', 'stranden-zeeland.html', 'zeeuwse-stadjes.html', 'deltawerken-bezoeken.html', 'zeeuwse-specialiteiten.html', 'veerse-meer.html', 'zeeland-herfst-winter.html', 'boeken.html', 'huisregels.html', 'algemene-voorwaarden.html', 'annuleringsvoorwaarden.html', 'privacyverklaring.html']
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'site')
fout = False
for bestand in PAGINAS:
    pad = os.path.join(root, bestand)
    origineel = open(pad).read()
    bron = seo(origineel, 'nl', bestand)
    if bron != origineel:
        open(pad, 'w').write(bron)
        print(bestand, 'seo blok bijgewerkt')
    for taal, tabel, regels in (('de', DE, DE_RE), ('en', EN, EN_RE)):
        h, missers = maak(bron, taal, tabel, regels, bestand)
        h = seo(h, taal, bestand)
        if missers:
            fout = True
            print(bestand, taal, 'ONVERTAALD:', missers)
        os.makedirs(os.path.join(root, taal), exist_ok=True)
        open(os.path.join(root, taal, bestand), 'w').write(h)
        print(taal + '/' + bestand, 'ok', len(h))
# sitemap.xml met alle pagina's in alle talen
import subprocess, datetime
def gewijzigd(bestand):
    # datum van de laatste commit van de Nederlandse bron, of vandaag bij niet gecommitte wijzigingen
    vuil = subprocess.run(['git', 'status', '--porcelain', bestand], cwd=root, capture_output=True, text=True).stdout.strip()
    datum = subprocess.run(['git', 'log', '-1', '--follow', '--format=%cs', '--', bestand], cwd=root, capture_output=True, text=True).stdout.strip()
    return datetime.date.today().isoformat() if vuil or not datum else datum
regels = ['<?xml version="1.0" encoding="UTF-8"?>',
          '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">']
for bestand in PAGINAS:
    for taal in ('nl', 'de', 'en'):
        regels += ['  <url>', f'    <loc>{pagina_url(bestand, taal)}</loc>', f'    <lastmod>{gewijzigd(bestand)}</lastmod>']
        regels += [f'    <xhtml:link rel="alternate" hreflang="{a}" href="{pagina_url(bestand, a)}"/>' for a in ('nl', 'de', 'en')]
        regels += [f'    <xhtml:link rel="alternate" hreflang="x-default" href="{pagina_url(bestand, 'nl')}"/>', '  </url>']
regels.append('</urlset>')
open(os.path.join(root, 'sitemap.xml'), 'w').write('\n'.join(regels) + '\n')
print('sitemap.xml ok')

sys.exit(1 if fout else 0)
